def solution(*args, **kwargs):
    import sys

    # Support both: arguments directly (as in tests) and stdin (as in problem)
    if args:
        x = int(args[0])
    else:
        data = sys.stdin.read().strip()
        if not data:
            return
        x = int(data)

    s = str(x)
    n = len(s)

    # Greedy observation:
    # For minimal digit sum with constraint <= x, either:
    # - x itself is optimal, or
    # - some number of the form (prefix-1) followed by all 9s is optimal.
    # We check all such candidates and pick the one with minimal digit sum,
    # and among those, the smallest numerically.
    def digit_sum(num_str: str) -> int:
        return sum(ord(c) - 48 for c in num_str)

    best = s
    best_sum = digit_sum(best)

    for i in range(n):
        if s[i] == '0':
            continue
        # Decrease prefix ending at i by 1
        prefix = s[:i]
        dec_digit = str(int(s[i]) - 1)
        candidate = prefix + dec_digit + '9' * (n - i - 1)
        # Remove leading zeros
        candidate = candidate.lstrip('0')
        if candidate == "" or candidate == "0":
            continue
        if int(candidate) > x:
            continue
        cs = digit_sum(candidate)
        if cs < best_sum or (cs == best_sum and int(candidate) < int(best)):
            best = candidate
            best_sum = cs

    # Also consider the largest number with fewer digits (all 9s)
    if n > 1:
        candidate = '9' * (n - 1)
        if int(candidate) > 0 and int(candidate) <= x:
            cs = digit_sum(candidate)
            if cs < best_sum or (cs == best_sum and int(candidate) < int(best)):
                best = candidate
                best_sum = cs

    # Output depends on invocation: if args, return; else print.
    if args:
        return int(best)
    else:
        print(best)

